import { describe, expect, it } from "vitest";
import {
  catalogueFont,
  catalogueFonts,
  catalogueTotalBytes,
  fontListResponse,
  readCatalogueFont,
} from "./fonts";

// The catalogue is generated by backend/scripts/generate_font_manifest.py and
// kept honest against the .ttf folder by backend's test_font_manifest.py.
// What is worth checking on this side is the contract the SPA and the sync
// loop depend on: the shape the font picker parses, and that a name in the
// catalogue really does resolve to bytes.

describe("the cloud font catalogue", () => {
  it("carries the fonts the repo ships", () => {
    expect(catalogueFonts.length).toBeGreaterThan(50);
    expect(catalogueTotalBytes).toBeGreaterThan(10_000_000);
  });

  it("answers /api/fonts in exactly the shape FontMetadata declares", () => {
    const { fonts } = fontListResponse();
    expect(fonts.length).toBe(catalogueFonts.length);
    for (const font of fonts) {
      expect(Object.keys(font).sort()).toEqual([
        "file",
        "italic",
        "name",
        "weight",
        "weight_title",
      ]);
      expect(typeof font.name).toBe("string");
      expect(font.name.length).toBeGreaterThan(0);
      expect(typeof font.weight).toBe("number");
      expect(typeof font.italic).toBe("boolean");
    }
  });

  it("does not leak the sync loop's byte sizes into the picker's payload", () => {
    // Harmless, but the SPA's FontMetadata has no `size` and the two lists
    // are compared field-by-field in the frontend's own tests.
    for (const font of fontListResponse().fonts) {
      expect("size" in font).toBe(false);
    }
  });

  it("resolves a name only when it is in the catalogue", () => {
    const first = catalogueFonts[0]!;
    expect(catalogueFont(first.file)?.size).toBe(first.size);
    expect(catalogueFont("NotAFont.ttf")).toBeUndefined();
    // The name becomes a filesystem path in readCatalogueFont, so a traversal
    // attempt must die at the lookup rather than later.
    expect(catalogueFont("../../../etc/passwd")).toBeUndefined();
    expect(catalogueFont("../fonts/CascadiaMono.ttf")).toBeUndefined();
  });

  it("reads real bytes for every font, of the size the manifest promises", async () => {
    // Every one, not a sample: a font whose bytes are missing fails its sync
    // silently otherwise, and the manifest is the only thing pointing at them.
    for (const font of catalogueFonts) {
      const bytes = await readCatalogueFont(font);
      expect(bytes.byteLength, `${font.file} is a different size on disk`).toBe(font.size);
    }
  });

  it("starts every font with a TrueType signature", async () => {
    // Cheap proof the copy step moved fonts and not, say, LFS pointers.
    for (const font of catalogueFonts.slice(0, 5)) {
      const bytes = await readCatalogueFont(font);
      const signature = bytes.readUInt32BE(0);
      // 0x00010000 (TrueType) or 'ttcf' / 'true' / 'OTTO' for the variants.
      expect([0x00010000, 0x74746366, 0x74727565, 0x4f54544f]).toContain(signature);
    }
  });
});
